using UnityEngine;
// Supplemental new-content roll. Never draws from Rewards/Placement/Events or Unity.Random.
public static class NewWeaponDrop {
 public static bool KnownRevision(string value){if(string.IsNullOrEmpty(value)||value.Length<5||value[0]!='N'||value[1]!='W'||value[3]!='|')return false;int count=value[2]-'0';string old=value.Substring(4);return count>=1&&count<=NewWeaponRegistry.EnabledCount&&(old=="B06-B4-R1"||old=="B06-B4"||old=="B06-B2");}
 public static string Revision(string old)=>"NW"+NewWeaponRegistry.EnabledCount+"|"+old;
 public static GearItem Preview(RunState run,string entityId,EnemyArchetype archetype){if(run==null||run.mode!=AdventureMode.ForestExploration||!KnownRevision(run.contentRevision)||string.IsNullOrEmpty(entityId)||archetype==EnemyArchetype.Boss)return null;string key="NW1/"+run.runId+"/"+run.regionInstanceId+"/"+run.seed.ToString(System.Globalization.CultureInfo.InvariantCulture)+"/"+entityId;double chance=NewWeaponRegistry.Number(key+"/chance")/4294967296.0;if(chance>=(archetype==EnemyArchetype.Elite?.08:.03))return null;int count=run.contentRevision[2]-'0';var type=(GearType)(11+NewWeaponRegistry.Number(key+"/type")%(uint)count);double q=NewWeaponRegistry.Number(key+"/quality")/4294967296.0;var quality=q<.005?GearQuality.Red:q<.04?GearQuality.Gold:q<.18?GearQuality.Purple:q<.55?GearQuality.Green:GearQuality.White;return NewWeaponRegistry.Create(type,quality,key);}
 public static void AfterDeath(CombatEnemy enemy){if(enemy==null||enemy.target==null||enemy.GetComponent<ForestBossBrain>()!=null)return;var flow=AdventureFlow.Find(enemy.target);var item=Preview(flow?.ActiveRun,enemy.entityId,enemy.archetype);if(item==null)return;var pickup=LootPickup.SpawnGear(item,enemy.transform.position+Vector3.up*.55f+Vector3.back*.4f);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(pickup.gameObject,enemy.gameObject.scene);}
}
